      if (Math.hypot(x - pc[0], z - pc[1]) < 4.6) continue;
      LCyl(g, 0.25, 0.28, G1 - 0.6, x, 0.5, z, COL, 10); LBox(g, 0.66, 0.4, 0.66, x, G1 - 0.6, z, CORN);
